   "summaryZh": "前自行车世界冠军 Rudi Altig 谈老年运动、主动休息与保持活力的意义。",
   "contentDe": "Rudi Altig zählt zu den erfolgreichsten Radrennfahrern der Welt. Im Jahre 1966 wurde er Straßen-Weltmeister der Profis. Die SZ befragte den heute 60-Jährigen zum Sport im Alter.\n\nSZ: Treiben Sie heute noch Sport?\nAltig: Man treibt immer ein bisschen Sport — Radfahren, Tennis, Golf, ein bisschen Laufen oder Joggen, wie man das heute nennt. Bewegung ist wichtig, damit man nicht alt wird, nicht rostet.\n\nSZ: Wie viel Zeit schenken Sie dem Sport?\nAltig: Das ist ganz unterschiedlich — je nachdem, wie es meine Zeit zulässt. Vier bis fünf Stunden wöchentlich werden es wohl sein. Manchmal bin ich auch bis in die Abendstunden aktiv.\n\nSZ: Raten Sie älteren Menschen zum Sport?\nAltig: Wenn man einen gesunden Körper hat, soll man Sport treiben. Aber jeder muss selbst herausfinden, welche Sportart für ihn geeignet ist."
