   "id": "ocr-chinesin-deutsch",
   "titleDe": "Chinesin, Deutsch",
   "titleZh": "中国女性，德语",
   "levelHint": "B2",
   "source": "《德语阅读教程 中级》OCR · DAAD Letter 1/1998",
