   "summaryZh": "Paul、Julia、Andreas 和 Sofie 在柏林街头偶遇，互相介绍并约去喝咖啡。",
   "contentDe": "Paul: Guten Tag, Andreas! Wie geht es?\nAndreas: Hallo, Paul! Prima. Das hier ist meine Freundin Julia.\nPaul: Hallo, Julia.\nJulia: Guten Tag. Bist du Studentin?\nPaul: Ja, ich studiere Kunst. Und du?\nJulia: Mathematik. Bist du aus Berlin?\nPaul: Nein, ich komme aus Hannover. Ich wohne hier im Studentenwohnheim. Du auch?\nJulia: Nein, ich wohne bei meinen Eltern.\nPaul: Was machst du hier?\nJulia: Ich warte auf meine Freundin. Wir wollen Kaffee trinken.\nPaul: Was? Du hast jetzt eine Freundin? Wie heißt sie?\nJulia: Sofie. Sie studiert Germanistik.\nPaul: Sofie? Und sie studiert Germanistik? Wie ist ihr Familienname?\nJulia: Wegner.\nPaul: Ach! Ich kenne Sofie! Wir wohnen zusammen im Studentenwohnheim!\nJulia: Wirklich?\nSofie: Hallo, Paul! Julia?? Was machst du denn hier?\nJulia: Hallo, Sofie!\nPaul: Sofie, das ist Andreas, mein Freund.\nSofie: Hallo, Andreas.\nAndreas: Hallo. Wollen wir einen Kaffee trinken?\nAlle: Eine gute Idee."
