   "id": "ocr-blitzroehren",
   "titleDe": "Wenn Blitze im Sand einschlagen",
   "titleZh": "闪电击中沙地时",
   "contentDe": "Tatsächlich sind es Sandröhren, die innen hohl sind. Sie entstehen, wenn Blitze im Sand einschlagen. Durch die Hitze des Blitzes wird der Sand im Inneren der Röhre herausgeschleudert und der geschmolzene Sand wird praktisch zu Rohglas.\n\nDas auffälligste Stück aus der Sammlung eines Blitzsammlers misst zwei Meter; leider sind nur Bruchstücke dieser Röhre vorhanden. Solche Funde zeigen, welche enormen Kräfte bei einem Gewitter wirken.",
