   "contentDe": "Ein Mann kommt in eine Zoohandlung und verlangt zehn Ratten. „Wozu brauchen Sie die denn?“ wundert sich der Verkäufer.\n\n„Ich habe meine Wohnung gekündigt und muss sie so verlassen, wie ich sie bezogen habe“, sagt der Mann."
