   "id": "ocr-schneemann-spatz",
   "titleDe": "Der Schneemann und der Spatz",
   "titleZh": "雪人与麻雀",
   "contentDe": "Gestern haben die Buben nach der Schule einen Schneemann gebaut. Es ist ein großer, kugelrunder Herr mit zwei Reihen Knöpfen und einer langen Nase.\n\nAm Morgen wacht der Spatzenvater auf. Er kommt unter dem Dach hervor und sieht den Schneemann im Garten. „Was ist das für ein großer Vogel?“ fragt er seine Kinder. Die Spatzenkinder lachen. „Das ist kein Vogel, das ist ein Schneemann!“",
