   "contentDe": "Frau Nentwich kommt aus Luzern in der Schweiz. Sie ist Sekretärin und spricht Deutsch, Englisch und Italienisch. In ihrer Freizeit liest sie gern und macht Wanderungen in den Bergen.\n\nHerr Bauer wohnt in Berlin und arbeitet als Lehrer. Er spricht Deutsch und Spanisch. Sein Hobby ist Musik; er spielt seit vielen Jahren Gitarre."
