   "source": "Wortkarte 原创语法卡",
   "sections": [
    {
     "heading": "entweder ... oder",
     "body": "二选一。",
     "examples": [
      {
       "de": "Entweder fahren wir mit dem Zug oder wir fliegen.",
       "zh": "我们要么坐火车，要么坐飞机。"
      }
     ]
    },
    {
     "heading": "sowohl ... als auch",
     "body": "两者都。",
     "examples": [
      {
       "de": "Sie spricht sowohl Deutsch als auch Englisch.",
       "zh": "她既会说德语也会说英语。"
      }
     ]
    },
    {
     "heading": "nicht nur ... sondern auch",
     "body": "不仅……而且。",
     "examples": [
      {
       "de": "Er ist nicht nur klug, sondern auch freundlich.",
       "zh": "他不仅聪明，而且友好。"
      }
     ]
    },
    {
     "heading": "weder ... noch",
     "body": "两者都不。",
     "examples": [
      {
       "de": "Ich habe weder Zeit noch Geld.",
       "zh": "我既没时间也没钱。"
      }
     ]
    },
    {
     "heading": "je ... desto",
     "body": "越……越……；desto 后动词提前。",
     "examples": [
      {
       "de": "Je mehr ich lerne, desto besser verstehe ich es.",
       "zh": "我学得越多，理解得越好。"
      }
     ]
    }
   ],
